package com.company.skillplatform.artifact.interfaces;import com.company.skillplatform.artifact.application.ArtifactService;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1")public class ArtifactController{private final ArtifactService service;public ArtifactController(ArtifactService s){service=s;}@GetMapping("/skill-versions/{versionId}/artifacts")List<ArtifactService.ArtifactView> list(@PathVariable Long versionId){return service.list(versionId);}}
